=== public/style.css ===
:root {
  --bg: #f5f6fa;
  --surface: #ffffff;
  --ink: #1b1e2b;
  --muted: #6b7280;
  --line: #e6e8ef;
  --primary: #ff5a3c;
  --primary-dark: #e5401f;
  --accent: #1190e6;
  --ok: #16a34a;
  --warn: #f59e0b;
  --bad: #e11d48;
  --radius: 14px;
  --shadow: 0 6px 24px rgba(20, 22, 40, .08);
  --shadow-sm: 0 2px 8px rgba(20, 22, 40, .06);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.5;
}
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, select, textarea { font-family: inherit; font-size: 1rem; }

.container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 16px; }

/* ---------- Topbar ---------- */
.topbar {
  position: sticky; top: 0; z-index: 50;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
  box-shadow: var(--shadow-sm);
}
.topbar-inner { display: flex; align-items: center; gap: 14px; height: 64px; }
.logo { display: flex; align-items: center; gap: 8px; font-family: 'Poppins', sans-serif; font-weight: 800; font-size: 1.25rem; }
.logo-mark {
  width: 34px; height: 34px; display: grid; place-items: center;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  color: #fff; border-radius: 10px; font-size: 1.1rem;
}
.logo-text .accent { color: var(--primary); }
.menu-btn { display: none; }

.search-wrap { flex: 1; max-width: 520px; margin: 0 auto; position: relative; }
.search-icon { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); font-size: .9rem; opacity: .6; }
#searchInput {
  width: 100%; padding: 11px 14px 11px 38px;
  border: 1.5px solid var(--line); border-radius: 999px;
  background: var(--bg); outline: none; transition: .15s;
}
#searchInput:focus { border-color: var(--primary); background: #fff; box-shadow: 0 0 0 3px rgba(255,90,60,.12); }

.top-actions { display: flex; align-items: center; gap: 8px; }
.link-btn { display: flex; align-items: center; gap: 6px; padding: 8px 10px; border-radius: 10px; color: var(--ink); font-weight: 500; transition: .15s; }
.link-btn:hover { background: var(--bg); }
.link-btn.center { width: 100%; justify-content: center; color: var(--muted); }
.cart-btn { position: relative; }
.badge {
  position: absolute; top: 2px; right: 2px; min-width: 20px; height: 20px; padding: 0 5px;
  background: var(--primary); color: #fff; font-size: .72rem; font-weight: 700;
  border-radius: 999px; display: grid; place-items: center;
}
.user-chip { display: flex; align-items: center; gap: 8px; padding: 4px 8px 4px 4px; border-radius: 999px; }
.user-chip:hover { background: var(--bg); }
.avatar { width: 32px; height: 32px; border-radius: 50%; background: linear-gradient(135deg,#3b82f6,#8b5cf6); color:#fff; display: grid; place-items: center; font-weight: 700; }
.user-name { max-width: 90px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; }

/* ---------- Botões ---------- */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 11px 18px; border-radius: 10px; font-weight: 600; transition: .15s; }
.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); box-shadow: 0 6px 16px rgba(255,90,60,.3); }
.btn-ghost { background: var(--bg); color: var(--ink); border: 1px solid var(--line); }
.btn-ghost:hover { border-color: #cfd3dd; }
.btn-danger { background: #fdecec; color: var(--bad); }
.btn-danger:hover { background: #fbd5db; }
.btn-block { width: 100%; }
.btn-sm { padding: 7px 12px; font-size: .85rem; }
.btn:disabled { opacity: .5; cursor: not-allowed; transform: none; box-shadow: none; }
.icon-btn { width: 40px; height: 40px; border-radius: 10px; font-size: 1.1rem; display: grid; place-items: center; }
.icon-btn:hover { background: var(--bg); }

/* ---------- Mobile search ---------- */
.mobile-search { display: none; position: sticky; top: 64px; z-index: 40; background: var(--surface); padding: 8px 16px; border-bottom: 1px solid var(--line); position: relative; }
.mobile-search .search-icon { left: 24px; }
.mobile-search input { width: 100%; padding: 10px 14px 10px 36px; border: 1.5px solid var(--line); border-radius: 999px; background: var(--bg); outline: none; }

/* ---------- Layout principal ---------- */
main { min-height: 60vh; padding-top: 20px; padding-bottom: 40px; }
.section-title { font-family: 'Poppins', sans-serif; font-size: 1.5rem; font-weight: 700; margin: 22px 0 14px; }
.section-title small { color: var(--muted); font-weight: 500; font-size: .9rem; margin-left: 8px; }
.muted { color: var(--muted); }

/* ---------- Hero ---------- */
.hero {
  display: grid; grid-template-columns: 1.3fr 1fr; gap: 20px;
  background: linear-gradient(120deg, #1c2340 0%, #2b3a67 60%, #34437a 100%);
  border-radius: 20px; overflow: hidden; color: #fff; padding: 0;
}
.hero-main { padding: 34px 36px; }
