        <div class="card-stock" style="margin-top:8px">${p.stock > 0 ? `${p.stock} unidades em estoque` : 'Produto esgotado'}</div>
        <div class="qty-row" id="pQtyRow" style="${p.stock > 0 ? '' : 'display:none'}">
